function executeScriptsFromHtml(html) {
  var scriptsFromHtml = /<script\b[^>]*>([\s\S]*?)<\/script>/gm;
  var matchedScripts;

  while (matchedScripts = scriptsFromHtml.exec(html)) {
    try {
      eval(matchedScripts[1]);
    } catch (ex) {
      console.error("error in blog script: ".concat(matchedScripts[1], ":"), ex);
    }
  }
}

exports.executeScriptsFromHtml = executeScriptsFromHtml;

exports.secondsToHms = function (numInSec) {
  numInSec = parseInt(numInSec);
  var h = Math.floor(numInSec / 3600);
  var m = Math.floor(numInSec % 3600 / 60);
  var s = Math.floor(numInSec % 3600 % 60);
  var hDisplay = h > 0 ? h < 10 ? "0" + h + ":" : h.toString() + ":" : "";
  var mDisplay = m > 0 ? m < 10 ? "0" + m + ":" : m.toString() + ":" : "00:";
  var sDisplay = s > 0 ? s < 10 ? "0" + s : s.toString() : "00";
  return hDisplay + mDisplay + sDisplay;
};

exports.getCookie = function (name) {
  var match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
  if (match) return match[2];
};

exports.testAdblock = function (cb) {
  var url = "https://ads.google.com";
  fetch(url, {
    method: 'PUT',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json'
    }
  }).then(cb(false)).catch(function () {
    cb(true);
  });
};

exports.formatDate = function (date, format) {
  var year = date.getFullYear();
  var month = date.getMonth() + 1;
  var day = date.getDate();

  switch (format) {
    case "YYYY-MM-DD":
      {
        return "".concat(year, "-").concat(String(month).padStart(2, '0'), "-").concat(String(day).padStart(2, '0'));
        ;
      }

    case "DD/MM/YYYY":
      {
        return "".concat(String(day).padStart(2, '0'), "/").concat(String(month).padStart(2, '0'), "/").concat(year);
      }

    case "DD-MM-YYYY":
      {
        return "".concat(String(day).padStart(2, '0'), "-").concat(String(month).padStart(2, '0'), "-").concat(year);
      }

    case "DD.MM.YYYY":
      {
        return "".concat(String(day).padStart(2, '0'), ".").concat(String(month).padStart(2, '0'), ".").concat(year);
      }
  }
};

